package org.example.project.model.data; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Component; import java.util.ArrayList; import java.util.List; @Component public class FavoritesWatchlist { private List<String> watchlist; private List<String> favorites; private UserProfile userProfile; @Autowired public FavoritesWatchlist(UserProfile userProfile) { this.userProfile = userProfile; this.watchlist = new ArrayList<>(); this.favorites = new ArrayList<>(); } public List<String> getWatchlist() { return watchlist; } public List<String> getFavorites() { return favorites; } public UserProfile getUserProfile() { return userProfile; } public void addToWatchlist(String movieId) { if (!watchlist.contains(movieId)) { watchlist.add(movieId); } } public void addToFavorites(String movieId) { if (!favorites.contains(movieId)) { favorites.add(movieId); } } public void removeFromWatchlist(String movieId) { watchlist.remove(movieId); } public void removeFromFavorites(String movieId) { favorites.remove(movieId); } }
